/** Reuses the accepted shortcut/learning/RANDOM/PRESET assertions against the NEW V35 schema. */
@Testcontainers
class SimulationPerformanceFlowPostgresTest {
    @Container static final PostgreSQLContainer<?> pg=new PostgreSQLContainer<>("postgres:16-alpine").withDatabaseName("dts_practice");
    static JdbcTemplate jdbc;static TransactionTemplate tx;static String oldHistory;
    final UUID user=UUID.randomUUID();final AtomicReference<Instant> now=new AtomicReference<>(Instant.now().plusSeconds(1).truncatedTo(java.time.temporal.ChronoUnit.MICROS));
    final ObjectMapper json=new ObjectMapper().findAndRegisterModules();
    SimulationBank.Snapshot bank;SimulationAccess access;SimulationExamAccess examAccess;SimulationBankClient banks;
    SimulationLearningRepository lessons;SimulationExamRepository exams;SimulationShortcutRepository store;
    SimulationLearningService learning;SimulationExamService engine;SimulationShortcutService shortcuts;SimulationPresetService presets;
    @BeforeAll static void migrate(){var ds=new DriverManagerDataSource(pg.getJdbcUrl(),pg.getUsername(),pg.getPassword());jdbc=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));flyway("33").migrate();oldHistory=history();assertEquals(1,flyway("34").migrate().migrationsExecuted);assertEquals(oldHistory,history());assertEquals(0,flyway("34").migrate().migrationsExecuted);assertEquals(1,flyway("35").migrate().migrationsExecuted);assertEquals(oldHistory,history());}
    static Flyway flyway(String version){return Flyway.configure().dataSource(pg.getJdbcUrl(),pg.getUsername(),pg.getPassword()).locations("classpath:db/migration").target(version).load();}
    static String history(){return jdbc.queryForObject("SELECT jsonb_agg(to_jsonb(h) ORDER BY installed_rank)::text FROM flyway_schema_history h WHERE version NOT IN ('34','35')",String.class);}
    @BeforeEach void setup(){
        var original=SimulationFixtures.published().snapshot();var rows=original.scenarios().stream().map(s->new SimulationBank.Scenario(s.scenarioId(),s.scenarioNumber(),s.chapterId(),s.title(),s.durationMs(),s.videoMediaId(),s.thumbnailMediaId(),s.hazardSign(),s.recognitionTip(),new SimulationBank.Timeline(17000,18000,19000,20000,21000,22000),s.video(),s.thumbnail())).toList();
        bank=new SimulationBank.Snapshot(original.bankVersion(),original.contentVersion(),original.assetVersion(),"scoring-shortcuts-fixture",original.sourceSha256(),original.assetManifestSha256(),original.manifestSha256(),original.chapters(),rows);
        lessons=new SimulationLearningRepository(jdbc,json);exams=new SimulationExamRepository(jdbc,json);store=new SimulationShortcutRepository(jdbc,json);access=mock(SimulationAccess.class);examAccess=mock(SimulationExamAccess.class);banks=mock(SimulationBankClient.class);
        var actor=new SimulationAccess.Actor(user,"fixture");when(access.learn()).thenReturn(actor);when(access.read(anyBoolean())).thenReturn(actor);when(examAccess.require(anyBoolean())).thenReturn(actor);when(banks.current()).thenReturn(bank);when(banks.load(any())).thenReturn(bank);when(banks.presets()).thenReturn(SimulationPresetFixtures.catalogue(bank));when(banks.preset(any())).thenReturn(SimulationPresetFixtures.version(bank,1,"v1"));
        var clock=mock(SimulationLearningClock.class);when(clock.now()).thenAnswer(a->now.get());
        var playback=mock(SimulationPlaybackClient.class);when(playback.resolve(any(),any())).thenAnswer(a->{SimulationLearningModel.Row r=a.getArgument(1);return new SimulationPlaybackClient.Response(r.snapshot.videoMediaId(),"http://localhost:9000/fixture",OffsetDateTime.now().plusSeconds(300),r.bank);});
        learning=new SimulationLearningService(access,banks,lessons,playback,clock);
        var media=mock(SimulationExamMediaClient.class);when(media.eligibility(any(),any(),any())).thenAnswer(a->{List<SimulationBank.Scenario> list=a.getArgument(2);return list.stream().map(s->new SimulationExamMediaClient.Eligible(s.videoMediaId(),true,s.durationMs(),s.video().videoTrackDurationMs(),"fixtureetag","READY")).toList();});
        when(media.playback(any(),any(),any(),anyBoolean())).thenAnswer(a->{SimulationExamModel.Row r=a.getArgument(1);SimulationExamModel.Frame f=a.getArgument(2);return new SimulationExamMediaClient.Video(r.id,f.position,f.playbackId,r.bank,r.manifest,f.snapshot.videoMediaId(),"http://localhost:9000/fixture",OffsetDateTime.now().plusSeconds(300),"video/mp4",f.duration,"CURRENT");});
        engine=new SimulationExamService(examAccess,banks,exams,media,new SimulationExamRules(),clock);shortcuts=new SimulationShortcutService(access,examAccess,lessons,exams,store,clock);presets=new SimulationPresetService(examAccess,banks,exams,clock);
    }
    @AfterEach void historyPreserved(){assertEquals(oldHistory,history());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*)FROM simulation_performance_outbox e JOIN simulation_exam_results r ON(e.payload->'data'->>'sourceId')::uuid=r.session_id WHERE e.event_type='SIMULATION_EXAM_COMPLETED' AND(e.payload->'data'->>'userId')::uuid=? AND((e.payload->'data'->>'score')::integer<>r.total_score OR e.payload->'data'->>'result'<>r.result_status)",Integer.class,user));}
    <T>T call(Supplier<T> f){return tx.execute(s->f.get());}
    SimulationExamModel.Session create(String mode){var p=SimulationPresetFixtures.version(bank,1,"v1");return call(()->engine.create(UUID.randomUUID(),new SimulationExamModel.Create(mode,"B",bank.bankVersion(),mode.equals("PRESET")?p.presetSetId():null,mode.equals("PRESET")?p.presetVersionId():null)));}
    SimulationShortcutModel.State state(SimulationExamModel.Session s){return call(()->shortcuts.state("EXAM",s.sessionId(),"B"));}
    SimulationShortcutModel.Request command(SimulationExamModel.Session s,Integer ms,String proof){return new SimulationShortcutModel.Request(UUID.randomUUID(),s.currentPosition(),s.playbackEventId(),ms,proof);}
    SimulationExamModel.Event event(SimulationExamModel.Session s,int ms){return new SimulationExamModel.Event(UUID.randomUUID(),s.currentPosition(),s.playbackEventId(),ms);}
    SimulationExamModel.Session enable(SimulationExamModel.Session s){return call(()->shortcuts.enable("EXAM",s.sessionId(),command(s,null,null),"B")).state().session();}
    SimulationExamModel.Session play(SimulationExamModel.Session s){var p=call(()->engine.playback(s.sessionId(),"B"));return call(()->engine.start(s.sessionId(),event(s,p.restartAtMs()),"B"));}
    SimulationExamModel.Session react(SimulationExamModel.Session s,int ms){int base=exams.frame(s.sessionId(),s.currentPosition()).segmentStart;Instant start=now.get();for(int t=base+3000;t<ms;t+=3000){now.set(start.plusMillis(t-base));int pos=t;call(()->engine.heartbeat(s.sessionId(),event(s,pos),"B"));}now.set(start.plusMillis(ms-base));return call(()->engine.reaction(s.sessionId(),event(s,ms),"B"));}
    SimulationShortcutModel.Ack next(SimulationExamModel.Session s){String proof=state(s).reactionAcknowledgement();return call(()->shortcuts.advance(s.sessionId(),command(s,null,proof),"B"));}
    SimulationExamModel.Session skipped(SimulationExamModel.Session s){return call(()->shortcuts.skip("EXAM",s.sessionId(),command(s,0,null),"B")).state().session();}
    SimulationLearningModel.Attempt lesson(){return call(()->learning.create(new SimulationLearningModel.Create(UUID.randomUUID(),bank.scenarios().getFirst().scenarioId(),"B",bank.bankVersion())));}
    SimulationLearningModel.Event levent(SimulationLearningModel.Attempt a,int ms){return new SimulationLearningModel.Event(UUID.randomUUID(),a.playbackEventId(),ms);}
    SimulationShortcutModel.Request lcommand(SimulationLearningModel.Attempt a,Integer ms){return new SimulationShortcutModel.Request(UUID.randomUUID(),1,a.playbackEventId(),ms,null);}
    SimulationLearningModel.Attempt lplay(SimulationLearningModel.Attempt a){call(()->learning.playback(a.attemptId()));return call(()->learning.start(a.attemptId(),levent(a,a.resumeAtMs())));}
    @Test void lessonSkip17432IsAbsoluteAndMatchesUnskippedPositiveScore(){
        var a=lesson();call(()->shortcuts.enable("LEARNING",a.attemptId(),lcommand(a,null),"B"));var started=lplay(a);var ack=call(()->shortcuts.skip("LEARNING",a.attemptId(),lcommand(started,0),"B"));var p=lplay(ack.state().attempt());Instant begin=now.get();now.set(begin.plusMillis(3000));call(()->learning.heartbeat(p.attemptId(),levent(p,13000)));now.set(begin.plusMillis(6000));call(()->learning.heartbeat(p.attemptId(),levent(p,16000)));now.set(begin.plusMillis(7432));call(()->learning.response(p.attemptId(),levent(p,17432)));assertEquals(17432,lessons.get(user,p.attemptId(),false).responseMs);assertEquals(5,SimulationLearningRules.score(bank.scenarios().getFirst().scoringTimeline(),lessons.get(user,p.attemptId(),false).responseMs));
        var direct=lplay(lesson());Instant full=now.get();for(int t=3000;t<17432;t+=3000){now.set(full.plusMillis(t));int ms=t;call(()->learning.heartbeat(direct.attemptId(),levent(direct,ms)));}now.set(full.plusMillis(17432));call(()->learning.response(direct.attemptId(),levent(direct,17432)));assertEquals(lessons.get(user,direct.attemptId(),false).responseMs,lessons.get(user,p.attemptId(),false).responseMs);
    }
    @Test void examSkip17432AndAdvancePreserveFivePoints(){var s=play(enable(create("RANDOM")));var after=play(skipped(s));after=react(after,17432);var done=next(after);assertEquals(2,done.state().position());var f=exams.frame(s.sessionId(),1);assertEquals(17432,f.responseMs);assertEquals(5,f.score);assertEquals("ADVANCE_AFTER_REACTION",done.state().completionReasons().get("1"));assertTrue(f.lastMs<f.duration);}
    @Test void legacySessionCannotSkipWithoutExplicitEnable(){var s=play(create("RANDOM"));assertFalse(state(s).enabled());assertFalse(state(s).canEnable());assertEquals("SIMULATION_SHORTCUT_NOT_ENABLED",assertThrows(SimulationShortcutFailure.class,()->call(()->shortcuts.skip("EXAM",s.sessionId(),command(s,0,null),"B"))).code);}
    @Test void legacyAlreadyStartedCannotUpgrade(){var s=play(create("RANDOM"));assertEquals("SIMULATION_SHORTCUT_POLICY_LOCKED",assertThrows(SimulationShortcutFailure.class,()->call(()->shortcuts.enable("EXAM",s.sessionId(),command(s,null,null),"B"))).code);}
    @Test void skipRequiresActualPlayingAndGrant(){var s=enable(create("RANDOM"));assertEquals("SIMULATION_SHORTCUT_NOT_PLAYING",assertThrows(SimulationShortcutFailure.class,()->call(()->shortcuts.skip("EXAM",s.sessionId(),command(s,0,null),"B"))).code);}
    @Test void skipOncePerPositionAndNoArbitrarySeek(){var s=play(enable(create("RANDOM")));var skipped=play(skipped(s));assertEquals(10000,exams.frame(s.sessionId(),1).segmentStart);assertEquals("SIMULATION_SHORTCUT_ALREADY_USED",assertThrows(SimulationShortcutFailure.class,()->call(()->shortcuts.skip("EXAM",s.sessionId(),command(skipped,10000,null),"B"))).code);assertThrows(BusinessException.class,()->call(()->engine.heartbeat(s.sessionId(),event(skipped,30000),"B")));}
    @Test void skipAfterResponseZeroIsDenied(){var s=react(play(enable(create("RANDOM"))),0);assertEquals("SIMULATION_SHORTCUT_REACTION_ALREADY_RECORDED",assertThrows(SimulationShortcutFailure.class,()->call(()->shortcuts.skip("EXAM",s.sessionId(),command(s,0,null),"B"))).code);}
    @Test void nextRequiresNonNullStoredReactionAndServerConfirmation(){var s=play(enable(create("RANDOM")));assertEquals("SIMULATION_SHORTCUT_REACTION_ACK_REQUIRED",assertThrows(SimulationShortcutFailure.class,()->call(()->shortcuts.advance(s.sessionId(),command(s,null,"0".repeat(64)),"B"))).code);var reacted=react(s,0);assertEquals("SIMULATION_SHORTCUT_REACTION_ACK_REQUIRED",assertThrows(SimulationShortcutFailure.class,()->call(()->shortcuts.advance(s.sessionId(),command(reacted,null,"0".repeat(64)),"B"))).code);assertNotNull(state(reacted).reactionAcknowledgement());assertEquals(2,next(reacted).state().position());assertEquals(0,exams.frame(s.sessionId(),1).responseMs);}
    @Test void skipLostAckRetryHasSameReceiptAndFreshCurrentState(){var s=play(enable(create("RANDOM")));var req=command(s,0,null);var first=call(()->shortcuts.skip("EXAM",s.sessionId(),req,"B"));var retry=call(()->shortcuts.skip("EXAM",s.sessionId(),req,"B"));assertEquals(first.receipt(),retry.receipt());assertEquals(first.state(),retry.state());assertEquals(0,exams.get(user,s.sessionId(),false).completedCount);}
    @Test void skipOldNonceHeartbeatAndEndedDoNotAdvance(){var s=play(enable(create("RANDOM")));skipped(s);assertThrows(SimulationExamFailure.class,()->call(()->engine.heartbeat(s.sessionId(),event(s,0),"B")));assertThrows(SimulationExamFailure.class,()->call(()->engine.complete(s.sessionId(),event(s,60000),"B")));assertEquals(0,exams.get(user,s.sessionId(),false).completedCount);}
    @Test void restartResetsCheckpointToZeroButRetainsFirstReaction(){var s=react(play(skipped(play(enable(create("RANDOM"))))),17432);var oldProof=state(s).reactionAcknowledgement();var restart=call(()->engine.restart(s.sessionId(),new SimulationExamModel.Restart(UUID.randomUUID(),1,s.playbackEventId()),"B"));assertEquals(0,exams.frame(s.sessionId(),1).segmentStart);assertEquals(17432,exams.frame(s.sessionId(),1).responseMs);assertNotEquals(oldProof,state(restart).reactionAcknowledgement());assertThrows(SimulationShortcutFailure.class,()->call(()->shortcuts.advance(s.sessionId(),command(restart,null,oldProof),"B")));}
    @Test void urlRenewalDoesNotResetAnchorOrGrantSeek(){var s=play(skipped(play(enable(create("RANDOM")))));Instant anchor=exams.frame(s.sessionId(),1).segmentStarted;var nonce=s.playbackEventId();now.set(now.get().plusSeconds(1));var p=call(()->engine.playback(s.sessionId(),"B"));assertEquals(10000,p.restartAtMs());assertEquals(anchor,exams.frame(s.sessionId(),1).segmentStarted);assertEquals(nonce,p.playbackEventId());assertThrows(BusinessException.class,()->call(()->engine.heartbeat(s.sessionId(),event(s,30000),"B")));}
    @Test void nextRetryAndLateAckNeverRollPositionBackward(){var s=react(play(enable(create("RANDOM"))),17432);var req=command(s,null,state(s).reactionAcknowledgement());var first=call(()->shortcuts.advance(s.sessionId(),req,"B"));var s2=react(play(first.state().session()),17432);next(s2);var late=call(()->shortcuts.advance(s.sessionId(),req,"B"));assertEquals(first.receipt(),late.receipt());assertEquals(3,late.state().position());assertTrue(late.state().shortcutRevision()>first.receipt().appliedRevision());}
    @Test void duplicateNextDifferentEventCannotAdvanceTwice(){var s=react(play(enable(create("RANDOM"))),17432);var proof=state(s).reactionAcknowledgement();next(s);assertThrows(SimulationShortcutFailure.class,()->call(()->shortcuts.advance(s.sessionId(),command(s,null,proof),"B")));assertEquals(1,exams.get(user,s.sessionId(),false).completedCount);}
    @Test void oldHeartbeatAndOldEndedAfterNextLeaveNewPositionUntouched(){var s=react(play(enable(create("RANDOM"))),17432);next(s);assertThrows(SimulationExamFailure.class,()->call(()->engine.heartbeat(s.sessionId(),event(s,17432),"B")));call(()->engine.complete(s.sessionId(),event(s,60000),"B"));assertEquals(1,exams.get(user,s.sessionId(),false).completedCount);assertEquals("NOT_STARTED",exams.frame(s.sessionId(),2).state);assertEquals(17432,exams.frame(s.sessionId(),1).responseMs);}
    @Test void concurrentNextAndClickCompleteOnePosition()throws Exception{var s=react(play(enable(create("RANDOM"))),17432);var proof=state(s).reactionAcknowledgement();try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var a=pool.submit(()->call(()->shortcuts.advance(s.sessionId(),command(s,null,proof),"B")));var b=pool.submit(()->{try{return call(()->shortcuts.advance(s.sessionId(),command(s,null,proof),"B"));}catch(SimulationShortcutFailure e){return null;}});try{a.get(10,TimeUnit.SECONDS);}catch(ExecutionException e){assertInstanceOf(SimulationShortcutFailure.class,e.getCause());}b.get(10,TimeUnit.SECONDS);}assertEquals(1,exams.get(user,s.sessionId(),false).completedCount);assertEquals(5,exams.frame(s.sessionId(),1).score);}
    @Test void eventConflictCannotChangePayloadOrReuseLegacyUuid(){var s=play(enable(create("RANDOM")));var req=command(s,0,null);call(()->shortcuts.skip("EXAM",s.sessionId(),req,"B"));assertThrows(SimulationShortcutFailure.class,()->call(()->shortcuts.skip("EXAM",s.sessionId(),new SimulationShortcutModel.Request(req.eventId(),1,req.playbackEventId(),1,null),"B")));assertThrows(SimulationExamFailure.class,()->call(()->engine.heartbeat(s.sessionId(),new SimulationExamModel.Event(req.eventId(),1,req.playbackEventId(),0),"B")));}
    @Test void ownerLicenseAndSecretsRemainProtected(){var s=enable(create("RANDOM"));var state=state(s);assertFalse(store.encode(state).contains(store.get("EXAM",s.sessionId()).secret.toString()));assertThrows(BusinessException.class,()->call(()->shortcuts.state("EXAM",s.sessionId(),"A1")));when(examAccess.require(anyBoolean())).thenReturn(new SimulationAccess.Actor(UUID.randomUUID(),"fixture-other"));assertThrows(SimulationExamFailure.class,()->state(s));}
    @Test void queryAndReviewDoNotWriteShortcutState(){var s=enable(create("RANDOM"));String before=jdbc.queryForObject("SELECT to_jsonb(s)::text FROM simulation_video_shortcut_state s WHERE target_id=?",String.class,s.sessionId());state(s);state(s);assertEquals(before,jdbc.queryForObject("SELECT to_jsonb(s)::text FROM simulation_video_shortcut_state s WHERE target_id=?",String.class,s.sessionId()));}
    @Test void pendingReactionCannotBeAdvancedWithoutItsConfirmation()throws Exception{
        var s=play(enable(create("RANDOM")));var stored=new CountDownLatch(1);var release=new CountDownLatch(1);
        try(var pool=Executors.newVirtualThreadPerTaskExecutor()){
            var reaction=pool.submit(()->tx.execute(status->{var r=engine.reaction(s.sessionId(),event(s,0),"B");stored.countDown();try{if(!release.await(5,TimeUnit.SECONDS))throw new AssertionError("fixture wait");}catch(InterruptedException e){throw new RuntimeException(e);}return r;}));
            try{assertTrue(stored.await(5,TimeUnit.SECONDS));assertNull(state(s).reactionAcknowledgement());var next=pool.submit(()->call(()->shortcuts.advance(s.sessionId(),command(s,null,"0".repeat(64)),"B")));release.countDown();reaction.get(10,TimeUnit.SECONDS);assertInstanceOf(SimulationShortcutFailure.class,assertThrows(ExecutionException.class,()->next.get(10,TimeUnit.SECONDS)).getCause());assertEquals(0,exams.get(user,s.sessionId(),false).completedCount);assertEquals(2,next(s).state().position());}finally{release.countDown();}
        }
    }
    @Test void nextAndStaleEndedAreSerializedWithoutDoubleAdvance()throws Exception{
        var s=react(play(enable(create("RANDOM"))),17432);String proof=state(s).reactionAcknowledgement();
        try(var pool=Executors.newVirtualThreadPerTaskExecutor()){
            var next=pool.submit(()->call(()->shortcuts.advance(s.sessionId(),command(s,null,proof),"B")));
            var ended=pool.submit(()->{try{return call(()->engine.complete(s.sessionId(),event(s,17432),"B"));}catch(SimulationExamFailure e){return null;}});
            next.get(10,TimeUnit.SECONDS);ended.get(10,TimeUnit.SECONDS);
        }
        assertEquals(1,exams.get(user,s.sessionId(),false).completedCount);assertEquals(17432,exams.frame(s.sessionId(),1).responseMs);assertEquals(5,exams.frame(s.sessionId(),1).score);
    }
    @Test void learningSkipCanCompleteWithRealRemainingElapsedAndFrozenScore(){
        var a=lesson();call(()->shortcuts.enable("LEARNING",a.attemptId(),lcommand(a,null),"B"));var started=lplay(a);var skipped=call(()->shortcuts.skip("LEARNING",a.attemptId(),lcommand(started,0),"B"));var ready=lplay(skipped.state().attempt());Instant anchor=now.get();
        now.set(anchor.plusSeconds(3));call(()->learning.heartbeat(ready.attemptId(),levent(ready,13000)));now.set(anchor.plusSeconds(6));call(()->learning.heartbeat(ready.attemptId(),levent(ready,16000)));now.set(anchor.plusMillis(7432));call(()->learning.response(ready.attemptId(),levent(ready,17432)));
        for(int t=20000;t<60000;t+=3000){now.set(anchor.plusMillis(t-10000));int ms=t;call(()->learning.heartbeat(ready.attemptId(),levent(ready,ms)));}
        now.set(anchor.plusMillis(50000));var done=call(()->learning.complete(ready.attemptId(),levent(ready,60000)));assertEquals(5,done.result().score());assertEquals(17432,done.result().firstResponseMs());assertEquals("COMPLETED",done.status());
    }
    @Test void learningInterruptAndRenewResumeAbsoluteVerifiedPosition(){
        var a=lesson();call(()->shortcuts.enable("LEARNING",a.attemptId(),lcommand(a,null),"B"));var started=lplay(a);var skipped=call(()->shortcuts.skip("LEARNING",a.attemptId(),lcommand(started,0),"B"));var current=lplay(skipped.state().attempt());now.set(now.get().plusSeconds(3));call(()->learning.heartbeat(current.attemptId(),levent(current,13000)));
        var interrupted=call(()->learning.interrupt(current.attemptId(),new SimulationLearningModel.Interrupt(UUID.randomUUID(),current.playbackEventId(),"NETWORK")));assertEquals(13000,interrupted.resumeAtMs());var resumed=lplay(interrupted);now.set(now.get().plusMillis(3000));call(()->learning.heartbeat(resumed.attemptId(),levent(resumed,16000)));now.set(now.get().plusMillis(1432));call(()->learning.response(resumed.attemptId(),levent(resumed,17432)));assertEquals(17432,lessons.get(user,resumed.attemptId(),false).responseMs);assertFalse(call(()->shortcuts.state("LEARNING",resumed.attemptId(),"B")).skipIntro().available());
    }
    SimulationExamModel.Session finishEarly(String mode,int total){var s=enable(create(mode));int left=total;for(int i=0;i<10;i++){var started=play(s);int points=Math.min(5,left);left-=points;int ms=points==0?0:22500-points*1000;var reacted=react(started,ms);s=next(reacted).state().session();}assertEquals("READY_TO_SUBMIT",s.status());var ready=s;assertThrows(SimulationExamFailure.class,()->call(()->engine.result(ready.sessionId(),"B")));var result=call(()->engine.submit(ready.sessionId(),new SimulationExamModel.Command(UUID.randomUUID()),"B"));assertEquals(total,call(()->engine.result(result.sessionId(),"B")).totalScore());return result;}
    @ParameterizedTest @CsvSource({"RANDOM,34,false","RANDOM,35,true","PRESET,34,false","PRESET,35,true","PRESET,50,true"})
    void tenNextThenSeparateSubmitProducesPinnedResultAndReadOnlyReview(String mode,int total,boolean passed){var result=finishEarly(mode,total);var r=call(()->engine.result(result.sessionId(),"B"));assertEquals(passed,r.passed());assertEquals(mode,r.mode());assertEquals(10,call(()->engine.review(result.sessionId(),"B")).items().size());assertEquals(10,state(result).completionReasons().size());assertTrue(state(result).completionReasons().values().stream().allMatch("ADVANCE_AFTER_REACTION"::equals));assertFalse(state(result).advanceAfterReaction().available());}
    @Test void latest50Then45Then30AndCancelledRetakeRemainCorrect(){finishEarly("PRESET",50);finishEarly("PRESET",45);var prior=call(()->presets.list("B")).items().getFirst();assertEquals(45,prior.latestCompletedScore());var retake=enable(create("PRESET"));call(()->engine.cancel(retake.sessionId(),new SimulationExamModel.Command(UUID.randomUUID()),"B"));assertEquals(prior.latestCompletedSessionId(),call(()->presets.list("B")).items().getFirst().latestCompletedSessionId());var last=finishEarly("PRESET",30);var item=call(()->presets.list("CE")).items().getFirst();assertEquals(30,item.latestCompletedScore());assertEquals(last.sessionId(),item.latestCompletedSessionId());}
    @Test void globalActiveAcrossModesAndLearningProjectionStayIsolated(){var s=enable(create("PRESET"));assertThrows(SimulationExamFailure.class,()->create("RANDOM"));String before=jdbc.queryForObject("SELECT count(*)::text FROM simulation_attempts WHERE user_id=?",String.class,user);var played=react(play(s),17432);next(played);assertEquals(before,jdbc.queryForObject("SELECT count(*)::text FROM simulation_attempts WHERE user_id=?",String.class,user));}
}
